// MIPS Register names and indices
const REGISTERS = {
  'zero': 0,  'at': 1,   'v0': 2,   'v1': 3,
  'a0': 4,    'a1': 5,   'a2': 6,   'a3': 7,
  's0': 16,   's1': 17,  's2': 18,  's3': 19,
  's4': 20,   's5': 21,  's6': 22,  's7': 23,
  't0': 8,    't1': 9,   't2': 10,  't3': 11,
  't4': 12,   't5': 13,  't6': 14,  't7': 15,
  't8': 24,   't9': 25,
  'k0': 26,   'k1': 27,
  'gp': 28,   'sp': 29,  'fp': 30,  'ra': 31
};

class MipsVM {
  constructor() {
    // Memory: 4GB addressable space (using Object for sparse storage)
    this.memory = new Uint8Array(0x10000000); // 256MB for practical purposes

    // 32 general-purpose registers
    this.registers = new Uint32Array(32);

    // Special registers
    this.pc = 0;           // Program counter
    this.hi = 0;           // High register (for mult/div)
    this.lo = 0;           // Low register (for mult/div)

    // Program state
    this.running = true;
    this.exitCode = 0;

    // File descriptors for syscalls (0=stdin, 1=stdout, 2=stderr)
    this.fileDescriptors = new Map();
    this.fileDescriptors.set(0, { type: 'stdin' });
    this.fileDescriptors.set(1, { type: 'stdout' });
    this.fileDescriptors.set(2, { type: 'stderr' });
    this.nextFd = 3;

    // Allocator state
    this.heapStart = 0x10000000;
    this.heapPtr = this.heapStart;

    // Screen buffer for Doom (320x200 pixels, 4 bytes per pixel)
    this.screenBuffer = Buffer.alloc(320 * 200 * 4);
    this.frameCount = 0;
  }

  loadELF(filename) {
    const data = fs.readFileSync(filename);

    // Parse ELF header
    const view = new DataView(data.buffer, data.byteOffset, data.length);

    // Check ELF magic
    if (view.getUint32(0, false) !== 0x464c457f) {
      throw new Error('Invalid ELF magic');
    }

    const e_entry = view.getUint32(24, true);
    const e_phoff = view.getUint32(28, true);
    const e_phnum = view.getUint16(44, true);

    console.log(`Entry point: 0x${e_entry.toString(16)}`);
    console.log(`Loading ${e_phnum} program headers...`);

    // Load program segments
    for (let i = 0; i < e_phnum; i++) {
      const phoff = e_phoff + i * 32;
      const p_type = view.getUint32(phoff, true);
      const p_offset = view.getUint32(phoff + 4, true);
      const p_vaddr = view.getUint32(phoff + 8, true);
      const p_filesz = view.getUint32(phoff + 16, true);
      const p_memsz = view.getUint32(phoff + 20, true);

      if (p_type === 1) { // PT_LOAD
        console.log(`  Loading segment: vaddr=0x${p_vaddr.toString(16)} filesz=0x${p_filesz.toString(16)}`);

        // Copy data to memory
        for (let j = 0; j < p_filesz; j++) {
          this.memory[p_vaddr + j] = data[p_offset + j];
        }

        // Zero out remaining memory if memsz > filesz
        for (let j = p_filesz; j < p_memsz; j++) {
          this.memory[p_vaddr + j] = 0;
        }
      }
    }

    this.pc = e_entry;

